function reportSalesInRange(){return sales.filter(s=>{const date=s.businessDate||dateFromTimestamp(s.closedAt||s.createdAt),inRange=date>=range.start&&date<=range.end;if(!inRange)return false;if(range.start===currentBusinessDate&&range.end===currentBusinessDate)return reportTime(s)>=currentBusinessDayStartedAtMs;return true})}
