function closeClosingDetail(){el.closingDetailDialog.close();selectedClosing=null}
function exportClosingDetailPdf(){if(!selectedClosing)return;const c=selectedClosing,rows=(c.products||[]).map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${formatNumber(p.quantity)}</td><td>${money(p.unitPrice)}</td><td>${money(p.total)}</td></tr>`).join(""),body=`<table><thead><tr><th>No</th><th>Ürün</th><th>Adet</th><th>Birim Fiyat</th><th>Toplam</th></tr></thead><tbody>${rows}</tbody></table>`;openCorporatePdf(`${formatDate(c.businessDate||c.id)} Gün Sonu Raporu`,body,[["Demlenen Çay",`${formatNumber(c.brewedPotCount)} Demlik`],["Esnaf Çay (Marka)",`${formatNumber(c.merchantTeaCount)} Adet`],["Nakit Satış",money(closingCashSales(c))],["Banka Satış",money(closingBank(c))],["Kart / POS Satış",money(closingCard(c))],["Bahşiş",money(c.tipTotal)],["Yuvarlama",money(c.roundingTotal)],["Toplam Satış",money(closingNetSales(c))]])}
function exportClosingDetailExcel(){if(!selectedClosing)return;const c=selectedClosing,rows=(c.products||[]).map(p=>`<Row><Cell><Data ss:Type="String">${xml(p.name)}</Data></Cell><Cell><Data ss:Type="Number">${num(p.quantity)}</Data></Cell><Cell><Data ss:Type="Number">${num(p.unitPrice)}</Data></Cell><Cell><Data ss:Type="Number">${num(p.total)}</Data></Cell></Row>`).join(""),summary=[["Demlenen Çay",num(c.brewedPotCount)],["Esnaf Çay (Marka)",num(c.merchantTeaCount)],["Toplam Satış",closingNetSales(c)],["Nakit Satış",closingCashSales(c)],["Banka Satış",closingBank(c)],["Kart / POS Satış",closingCard(c)],["Bahşiş",num(c.tipTotal)],["Hesap Yuvarlama",num(c.roundingTotal)],["Kapanan Adisyon",num(c.orderCount)]].map(x=>`<Row><Cell><Data ss:Type="String">${x[0]}</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${x[1]}</Data></Cell></Row>`).join(""),content=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Gün Sonu"><Table><Row><Cell><Data ss:Type="String">Ürün</Data></Cell><Cell><Data ss:Type="String">Adet</Data></Cell><Cell><Data ss:Type="String">Birim Fiyat</Data></Cell><Cell><Data ss:Type="String">Toplam</Data></Cell></Row>${rows}${summary}</Table></Worksheet></Workbook>`;download(content,`gun-sonu-${c.businessDate||c.id}.xls`,"application/vnd.ms-excel")}

function exportPdf(){const rows=report.products.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${esc(categoryName(p.categoryId))}</td><td>${formatNumber(p.quantity)}</td><td>${money(p.total)}</td></tr>`).join(""),body=`<table><thead><tr><th>No</th><th>Ürün</th><th>Kategori</th><th>Adet</th><th>Toplam</th></tr></thead><tbody>${rows}</tbody></table>`;openCorporatePdf(`Satış Raporu — ${formatDate(range.start)}${range.start===range.end?"":` / ${formatDate(range.end)}`}`,body,[["Nakit Gelir",money(report.cashTotal)],["Banka Geliri",money(report.transferTotal)],["Kart / POS Geliri",money(report.cardTotal)],["Bahşiş",money(report.tipTotal)],["Yuvarlama",money(report.roundingTotal)],["İkram",`${formatNumber(report.giftCount)} Adet`],["Esnaf Çay (Marka)",`${formatNumber(report.merchantTeaCount)} Adet`],["Toplam Satış",money(report.salesTotal)]])}
function exportExcel(){const rows=report.products.map(p=>`<Row><Cell><Data ss:Type="String">${xml(p.name)}</Data></Cell><Cell><Data ss:Type="String">${xml(categoryName(p.categoryId))}</Data></Cell><Cell><Data ss:Type="Number">${p.quantity}</Data></Cell><Cell><Data ss:Type="Number">${p.total}</Data></Cell></Row>`).join(""),summary=[["Toplam Satış",report.salesTotal],["Nakit Gelir",report.cashTotal],["Banka Geliri",report.transferTotal],["Kart / POS Geliri",report.cardTotal],["Bahşiş",report.tipTotal],["Hesap Yuvarlama",report.roundingTotal],["İkram Adedi",report.giftCount],["Esnaf Çay (Marka)",report.merchantTeaCount],["Kapanan Adisyon",report.orderCount]].map(x=>`<Row><Cell><Data ss:Type="String">${x[0]}</Data></Cell><Cell/><Cell/><Cell><Data ss:Type="Number">${x[1]}</Data></Cell></Row>`).join(""),content=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Satış Raporu"><Table><Row><Cell><Data ss:Type="String">Ürün</Data></Cell><Cell><Data ss:Type="String">Kategori</Data></Cell><Cell><Data ss:Type="String">Adet</Data></Cell><Cell><Data ss:Type="String">Toplam</Data></Cell></Row>${rows}${summary}</Table></Worksheet></Workbook>`;download(content,`satis-raporu-${range.start}-${range.end}.xls`,"application/vnd.ms-excel")}

function periodRange(type){const d=new Date(`${today()}T12:00:00`);if(type==="week"){const day=(d.getDay()+6)%7,start=new Date(d);start.setDate(d.getDate()-day);return{start:iso(start),end:iso(d)}}if(type==="month")return{start:`${today().slice(0,7)}-01`,end:today()};return{start:today(),end:today()}}
function emptyReport(){return{salesTotal:0,cashTotal:0,transferTotal:0,cardTotal:0,cashExpenseTotal:0,bankExpenseTotal:0,creditCardExpenseTotal:0,expenseTotal:0,itemCount:0,orderCount:0,giftCount:0,tipTotal:0,roundingTotal:0,merchantTeaCount:0,merchantMarkaCount:0,merchantTopupTotal:0,products:[],expenseMovements:[],expenseGroups:[]}}
function sumBillableItems(items){return(items||[]).filter(x=>!x.complimentary).reduce((sum,x)=>sum+num(x.unitPrice)*num(x.quantity),0)}
function movementDate(x){return String(x.operationDate||dateFromTimestamp(x.createdAt)||"")}
function movementPackages(x,stock){if(num(x.packageCount)>0)return num(x.packageCount);if(x.enteredUnit&&(x.enteredUnit===stock.packageUnit||x.enteredUnit==="koli"))return num(x.enteredAmount);return num(x.amount)/Math.max(1,num(x.unitsPerPackage)||num(stock.unitsPerPackage)||1)}
function movementPurchase(x,stock){if(num(x.purchaseTotal)>0)return num(x.purchaseTotal);if(x.purchasePriceBasis==="total")return num(x.purchasePrice);if(x.purchasePriceBasis==="package")return num(x.purchasePrice)*movementPackages(x,stock);if(x.purchasePriceBasis==="unit")return num(x.purchasePrice)*num(x.amount);return 0}
function categoryName(id){return catalog.categories.find(c=>c.id===id)?.name||(id==="other"?"Diğer":"Kategorisiz")}
function today(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Istanbul"}).format(new Date())}
function iso(d){return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Istanbul"}).format(d)}
function dateFromTimestamp(v){const d=v?.toDate?.();return d?new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Istanbul"}).format(d):""}
function reportTime(v){return v.closedAt?.toMillis?.()||v.createdAt?.toMillis?.()||num(v.closedAtMs)||num(v.createdAtMs)}
function formatDate(v){const [y,m,d]=String(v||"").split("-");return y&&m&&d?`${d}.${m}.${y}`:"—"}
function formatDateTime(v){if(!num(v))return"—";return new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Europe/Istanbul"}).format(new Date(num(v)))}
function formatTime(v){if(!num(v))return"—";return new Intl.DateTimeFormat("tr-TR",{hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Europe/Istanbul"}).format(new Date(num(v)))}
function num(v){return Number(v)||0}
function money(v){return new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY",minimumFractionDigits:num(v)%1?2:0}).format(num(v))}
function formatNumber(v){return new Intl.NumberFormat("tr-TR",{maximumFractionDigits:2}).format(num(v))}
function displayUnit(v){const value=String(v||"");return value?value.charAt(0).toLocaleUpperCase("tr-TR")+value.slice(1).toLocaleLowerCase("tr-TR"):""}
function updateClock(){const n=new Date();$("currentTime").textContent=new Intl.DateTimeFormat("tr-TR",{hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Europe/Istanbul"}).format(n);$("currentDate").textContent=new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"2-digit",timeZone:"Europe/Istanbul"}).format(n).replace(/\./g,"/")}
function show(message){clearTimeout(toastTimer);el.toast.textContent=message;el.toast.classList.add("show");toastTimer=setTimeout(()=>el.toast.classList.remove("show"),3000)}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function xml(v){return String(v??"").replace(/[<>&'"]/g,c=>({"<":"&lt;",">":"&gt;","&":"&amp;","'":"&apos;",'"':"&quot;"}[c]))}
function openCorporatePdf(title,body,totals){const popup=window.open("","_blank","width=1000,height=760");if(!popup)return show("PDF penceresi açılamadı. Açılır pencereye izin verin.");const logo=new URL("../assets/images/logo.png",location.href).href,created=new Intl.DateTimeFormat("tr-TR",{dateStyle:"full",timeStyle:"short",timeZone:"Europe/Istanbul"}).format(new Date());popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title><style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{margin:0;color:#342522;font:12px Arial,sans-serif}.watermark{position:fixed;inset:20% 15%;width:70%;height:60%;object-fit:contain;opacity:.045;z-index:-1}.head{display:flex;justify-content:space-between;gap:20px;border-bottom:3px solid #7d1b24;padding-bottom:12px}.brand img{width:90px}.brand p{margin:2px 0}.date{text-align:right}.title{text-align:center;color:#7d1b24;margin:22px 0 14px}table{width:100%;border-collapse:collapse}thead{display:table-header-group}th{background:#7d1b24;color:#fff}th,td{padding:9px;border:1px solid #d8c6ba;text-align:left}tbody tr:nth-child(even){background:#fff7ef}.totals{width:50%;margin:16px 0 0 auto;border:1px solid #d8c6ba}.totals div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #eaded6}.totals div:last-child{border:0;background:#fff2e2;color:#7d1b24;font-weight:bold}</style></head><body><img class="watermark" src="${logo}"><header class="head"><div class="brand"><img src="${logo}"><p><b>Fatih Ali Altınlı</b></p><p>0554 118 08 06</p><p>Ulukavak Mah. Osmancık Cad. No:285<br>Çorum/Merkez</p></div><div class="date"><b>Oluşturma Tarihi</b><p>${created}</p></div></header><h1 class="title">${esc(title)}</h1>${body}<section class="totals">${totals.map(x=>`<div><span>${x[0]}</span><b>${x[1]}</b></div>`).join("")}</section><script>window.onload=()=>setTimeout(()=>window.print(),350)<\/script></body></html>`);popup.document.close()}
